CacheProbe(Context context) { this.context = context; try { bookClass = Class.forName("com.simplereader.app.data.entity.Book"); getId = bookClass.getMethod("getId"); getFileName = bookClass.getMethod("getFileName"); getFileSize = bookClass.getMethod("getFileSize"); getFilePath = bookClass.getMethod("getFilePath"); Class<?> loaderClass = Class.forName("com.simplereader.app.reader.ReaderDocumentLoader"); loader = loaderClass.getField("INSTANCE").get(null); resolveDocument = loaderClass.getMethod("resolveDocument", Context.class, bookClass); loadDocument = loaderClass.getMethod("load", Context.class, bookClass, boolean.class); Class<?> documentFileClass = Class.forName("androidx.documentfile.provider.DocumentFile"); docGetName = documentFileClass.getMethod("getName"); docLength = documentFileClass.getMethod("length"); Class<?> readerDocClass = Class.forName("com.simplereader.app.reader.ReaderDocument"); readerDocGetText = readerDocClass.getMethod("getText"); readerDocGetSourceSize = readerDocClass.getMethod("getSourceSize"); readerDocGetSourceModified = readerDocClass.getMethod("getSourceModified"); Class<?> profileClass = Class.forName("com.simplereader.app.reader.page.ReaderCacheProfile"); profile = profileClass.getField("INSTANCE").get(null); currentTextSizeSp = profileClass.getMethod("currentTextSizeSp", Context.class); createSettings = profileClass.getMethod("createSettings", Context.class, float.class, Integer.class, Integer.class, Integer.class, Integer.class, Integer.class, Integer.class); Class<?> settingsClass = Class.forName("com.simplereader.app.reader.page.ReaderLayoutSettings"); stableHash = settingsClass.getMethod("stableHash"); Class<?> pageClass = Class.forName("com.simplereader.app.reader.page.PageCacheStore"); pageStore = pageClass.getField("INSTANCE").get(null); hasCurrentCatalog = pageClass.getMethod("hasCurrentCatalog", Context.class, long.class, String.class, Long.class); textFingerprint = pageClass.getMethod("textFingerprint", String.class); Class<?> identityClass = Class.forName("com.simplereader.app.reader.page.PageCacheStore$CacheIdentity"); cacheIdentityCtor = identityClass.getConstructor(long.class, String.class, long.class, long.class, String.class, String.class, int.class); loadPages = pageClass.getMethod("loadPages", Context.class, identityClass, String.class); Class<?> readerBookClass = Class.forName("com.simplereader.app.reader.page.ReaderBook"); readerBookGetPages = readerBookClass.getMethod("getPages"); try { Class<?> txtParser = Class.forName("com.simplereader.app.parser.TxtParser"); catalogRuleVersion = txtParser.getField("CATALOG_RULE_VERSION").getInt(null); } catch (Throwable ignored) { catalogRuleVersion = 111; } ready = true; } catch (Throwable ignored) { ready = false; } }
boolean hasReusableCurrentCache(Object book) { if (!ready || book == null) return false; try { long id = ((Number) getId.invoke(book)).longValue(); String fileName = (String) getFileName.invoke(book); Long fileSize = (Long) getFileSize.invoke(book); String filePath = (String) getFilePath.invoke(book); Object source = resolveDocument.invoke(loader, context, book); if (source != null) { Object n = docGetName.invoke(source); if (n instanceof String && ((String) n).trim().length() > 0) fileName = (String) n; Object length = docLength.invoke(source); if (length instanceof Number) { long len = ((Number) length).longValue(); if (len >= 0L) fileSize = Long.valueOf(len); } } Object catalog = hasCurrentCatalog.invoke(pageStore, context, Long.valueOf(id), fileName, fileSize); if (!Boolean.TRUE.equals(catalog)) return false; Object document = loadDocument.invoke(loader, context, book, Boolean.FALSE); if (document == null) return false; String text = (String) readerDocGetText.invoke(document); if (text == null) return false; long sourceSize = ((Number) readerDocGetSourceSize.invoke(document)).longValue(); long sourceModified = ((Number) readerDocGetSourceModified.invoke(document)).longValue(); float textSize = ((Number) currentTextSizeSp.invoke(profile, context)).floatValue(); Object settings = createSettings.invoke(profile, context, Float.valueOf(textSize), null, null, null, null, null, null); if (settings == null) return false; String settingsHash = (String) stableHash.invoke(settings); String fingerprint = (String) textFingerprint.invoke(pageStore, text); Object identity = cacheIdentityCtor.newInstance(Long.valueOf(id), filePath, Long.valueOf(sourceSize), Long.valueOf(sourceModified), settingsHash, fingerprint, Integer.valueOf(catalogRuleVersion)); Object cached = loadPages.invoke(pageStore, context, identity, text); if (cached == null) return false; Object pages = readerBookGetPages.invoke(cached); return pages instanceof List && !((List<?>) pages).isEmpty(); } catch (Throwable ignored) { return false; } }
