private static void clearAllDerived(Context context) { try { Class<?> pageClass = Class.forName("com.simplereader.app.reader.page.PageCacheStore"); Object store = pageClass.getField("INSTANCE").get(null); Method clear = pageClass.getMethod("clearAllDerivedCatalogAndPages", Context.class); clear.invoke(store, context); } catch (Throwable ignored) {} }
private static void finalizePendingSuccess(Context a) { SharedPreferences sp = a.getSharedPreferences(PREF, Context.MODE_PRIVATE); if (sp.getInt("pending", 0) != 1) return; SharedPreferences.Editor e = sp.edit(); e.putInt("completed_count", sp.getInt("completed_count", 0) + 1); e.putInt("pending", 0); e.putLong("last_update", System.currentTimeMillis()); e.apply(); }
private static void classifyPending(Context a, String outcome, String reason) { SharedPreferences sp = a.getSharedPreferences(PREF, Context.MODE_PRIVATE); if (sp.getInt("pending", 0) != 1) return; String title = sp.getString("last_title", ""); SharedPreferences.Editor e = sp.edit().putInt("pending", 0).putLong("last_update", System.currentTimeMillis()); if ("fail".equals(outcome)) { e.putInt("failed_count", sp.getInt("failed_count", 0) + 1); String detail = sp.getString("failure_details", ""); String stage = failureStage(reason); String line = "- " + (title == null || title.length() == 0 ? "（未知书名）" : title) + "\n  阶段：" + stage + "\n  原因：" + cleanReason(reason) + "\n"; e.putString("failure_details", (detail == null ? "" : detail) + line); } else if ("skip".equals(outcome)) { e.putInt("skipped_count", sp.getInt("skipped_count", 0) + 1); String detail = sp.getString("skip_details", ""); String line = "- " + (title == null || title.length() == 0 ? "（未知书名）" : title) + "：" + cleanReason(reason) + "\n"; e.putString("skip_details", (detail == null ? "" : detail) + line); } e.apply(); updateBody(a, "运行中", ""); }
private static String failureStage(String raw) { String s = raw == null ? "" : raw; if (s.contains("分页结果为空")) return "分页"; if (s.contains("缓存写入") || s.contains("缓存页数") || s.contains("章节校验") || s.contains("重新读取")) return "分页缓存写入/校验"; if (s.contains("SecurityException") || s.contains("Permission") || s.contains("EACCES")) return "文件访问权限"; if (s.contains("FileNotFound") || s.contains("NoSuchFile") || s.contains("ENOENT") || s.contains("文件")) return "文件读取"; if (s.contains("OutOfMemory")) return "分页/内存"; if (s.contains("目录") || s.contains("chapter") || s.contains("Chapter")) return "目录识别"; return "目录识别/分页处理"; }
private static String cleanReason(String raw) { if (raw == null || raw.trim().length() == 0) return "未知异常（未提供异常文本）"; String s = raw.replace('\n', ' ').replace('\r', ' ').trim(); return s.length() > 1200 ? s.substring(0, 1200) + "…" : s; }
private static int classified(SharedPreferences sp) { return sp.getInt("completed_count", 0) + sp.getInt("failed_count", 0) + sp.getInt("skipped_count", 0); }
private static void updateBody(Context a, String state, String currentTitle) { SharedPreferences sp = a.getSharedPreferences(PREF, Context.MODE_PRIVATE); int count = Math.min(LIMIT, Math.max(0, sp.getInt("count", 0))); if (count <= 0) return; String mode = sp.getString("mode", lastMode == null ? "" : lastMode); long started = sp.getLong("started_at", System.currentTimeMillis()); long now = System.currentTimeMillis(); int scan = Math.max(0, sp.getInt("scan_total", 0)); int target = Math.max(0, sp.getInt("target_total", 0)); int excluded = Math.max(0, sp.getInt("excluded_success", 0)); int success = Math.max(0, sp.getInt("completed_count", 0)); int failed = Math.max(0, sp.getInt("failed_count", 0)); int skipped = Math.max(0, sp.getInt("skipped_count", 0)); int done = success + failed + skipped; int pending = sp.getInt("pending", 0) == 1 ? 1 : 0; int shownCurrent = Math.min(target, done + pending); double percent = target > 0 ? shownCurrent * 100.0 / target : ("已完成".equals(state) ? 100.0 : 0.0); int unclassified = Math.max(0, target - done); String failures = sp.getString("failure_details", ""); String skips = sp.getString("skip_details", ""); StringBuilder body = new StringBuilder(); body.append("操作：").append(modeTitle(mode)).append("（目录识别 + 完整分页缓存）\n"); body.append("状态：").append(state).append("\n"); body.append("开始：").append(fullStamp(started)).append("\n"); body.append("更新：").append(fullStamp(now)).append("\n"); if (scan > 0) body.append("扫描书架：").append(scan).append(" 本\n"); if (MODE_NO_CATALOG.equals(mode)) body.append("已成功可复用（排除）：").append(excluded).append(" 本\n"); body.append("本次目标：").append(target).append(" 本\n"); body.append("处理进度：").append(shownCurrent).append(" / ").append(target).append("（").append(String.format(Locale.getDefault(), "%.1f", percent)).append("%）\n"); if (currentTitle != null && currentTitle.length() > 0) body.append("当前：").append(currentTitle).append("\n"); else { String last = sp.getString("last_title", ""); if (sp.getInt("pending", 0) == 1 && last != null && last.length() > 0) body.append("当前：").append(last).append("\n"); } body.append("成功：").append(success).append(" 本；失败：").append(failed).append(" 本；跳过：").append(skipped).append(" 本\n"); if (("已完成".equals(state) || state.contains("未归类")) && unclassified > 0) body.append("未归类：").append(unclassified).append(" 本（日志事件未完整闭合，禁止视为完全成功）\n"); if (failed > 0) { body.append("\n失败明细：\n"); body.append(failures == null || failures.length() == 0 ? "- 有失败计数，但未捕获异常文本\n" : failures); } if (skipped > 0) { body.append("\n跳过明细：\n"); body.append(skips == null ? "" : skips); } sp.edit().putString("title_0", modeTitle(mode) + " · " + stamp(started)).putString("body_0", body.toString()).putLong("last_update", now).apply(); }
public static void show(final Activity activity) { if (activity == null || activity.isFinishing()) return; purgeLegacy(activity); final SharedPreferences sp = activity.getSharedPreferences(PREF, Context.MODE_PRIVATE); int count = Math.min(LIMIT, Math.max(0, sp.getInt("count", 0))); if (count <= 0) { new AlertDialog.Builder(activity).setTitle("操作日志").setMessage("暂无操作日志").setNegativeButton("关闭", null).show(); return; } final CharSequence[] titles = new CharSequence[count]; for (int i = 0; i < count; i++) titles[i] = sp.getString("title_" + i, "目录缓存"); new AlertDialog.Builder(activity).setTitle("操作日志").setItems(titles, new DialogInterface.OnClickListener() { @Override public void onClick(DialogInterface dialog, int which) { showDetail(activity, sp, which); } }).setNegativeButton("关闭", null).show(); }
private static void showDetail(final Activity activity, final SharedPreferences sp, int index) { final String title = sp.getString("title_" + index, "操作日志"); final String body = sp.getString("body_" + index, "暂无结果"); final TextView text = new TextView(activity); text.setText(body); text.setTextSize(14f); text.setTextIsSelectable(true); int pad = dp(activity, 14); text.setPadding(pad, dp(activity, 10), pad, dp(activity, 16)); final ScrollView scroll = new ScrollView(activity); scroll.setFillViewport(true); scroll.addView(text); final SeekBar seek = new SeekBar(activity); seek.setMax(1000); seek.setProgress(0); LinearLayout root = new LinearLayout(activity); root.setOrientation(LinearLayout.VERTICAL); root.addView(scroll); root.addView(seek); final boolean[] dragging = new boolean[] { false }; seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener() { @Override public void onProgressChanged(SeekBar bar, int progress, boolean fromUser) { if (!fromUser) return; int range = Math.max(0, text.getHeight() - scroll.getHeight()); scroll.scrollTo(0, (int)(((long)range * progress) / 1000L)); } @Override public void onStartTrackingTouch(SeekBar bar) { dragging[0] = true; } @Override public void onStopTrackingTouch(SeekBar bar) { dragging[0] = false; } }); scroll.setOnScrollChangeListener(new View.OnScrollChangeListener() { @Override public void onScrollChange(View v, int sx, int sy, int oldx, int oldy) { if (dragging[0]) return; int range = Math.max(0, text.getHeight() - scroll.getHeight()); int progress = range <= 0 ? 0 : (int)(((long)sy * 1000L) / range); seek.setProgress(Math.max(0, Math.min(1000, progress))); } }); new AlertDialog.Builder(activity).setTitle(title).setView(root).setPositiveButton("复制", new DialogInterface.OnClickListener() { @Override public void onClick(DialogInterface dialog, int which) { Object service = activity.getSystemService(Context.CLIPBOARD_SERVICE); if (service instanceof ClipboardManager) ((ClipboardManager)service).setPrimaryClip(ClipData.newPlainText("操作日志", body)); } }).setNegativeButton("关闭", null).show(); }
private static int safeInt(String value) { try { return Integer.parseInt(value); } catch (Throwable ignored) { return 0; } }
private static String stamp(long now) { return new SimpleDateFormat("MM-dd HH:mm:ss", Locale.getDefault()).format(new Date(now)); }
private static String fullStamp(long now) { return new SimpleDateFormat("yyyy-MM-dd HH:mm:ss", Locale.getDefault()).format(new Date(now)); }
private static int dp(Context context, int value) { float d = context.getResources().getDisplayMetrics().density; return Math.max(1, (int)(value * d + 0.5f)); }
